<?php
namespace App\Http\Controllers\Auth;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;class AuthenticatedSessionController extends Controller{function create(){return view('auth.login');}function store(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($c,$r->boolean('remember')))return back()->withErrors(['email'=>'Invalid credentials']);$r->session()->regenerate();return redirect()->route('dashboard');}function destroy(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}}
